14	    @Contract("_, _, _ -> new")
15	    public static @NotNull Vec3d pseudoReflect(Vec3d ray, @NotNull Vec3i plane, double fresnel) {
16	        // Fresnels on a 1-30 scale
17	        // TODO account for http://hyperphysics.phy-astr.gsu.edu/hbase/Tables/indrf.html
18	
19	        // `plane` is always exactly one of the 6 axis-unit directions (never a general/oblique
20	        // normal), so the full ray - 2*dot(ray,n)*n mirror formula collapses to a per-axis check:
21	        // scale the component on the crossed axis by (1 - fresnel), leave the other two alone.
22	        // fresnel=2 is a full mirror reflection; smaller values blend in the refraction approximation.
23	        return new Vec3d(
24	                plane.getX() != 0 ? ray.x * (1 - fresnel) : ray.x,
25	                plane.getY() != 0 ? ray.y * (1 - fresnel) : ray.y,
26	                plane.getZ() != 0 ? ray.z * (1 - fresnel) : ray.z
27	        );
28	    }
