38	    /**
39	     * Alignment {@code a = (ray_norm · pol_norm)^2} &isin; [0,1] &mdash; squared, so sign/side of
40	     * the polarization axis doesn't matter. Not yet implemented &mdash; always throws.
41	     */
42	    public static double polarAlignment(@NotNull Vec3d rayNorm, @NotNull Vec3d polNorm) {
43	        double dot = rayNorm.dotProduct(polNorm);
44	        return dot * dot;
45	    }
