47	    /**
48	     * Blended "effective ray norm": {@code normalize(restrict(rayNorm) + normalize(octantCenter -
49	     * incidentPoint))}. The incident-angle term ({@code rayNorm}) is first restricted to whichever
50	     * single axis {@code polNorm} is dominant on (the same axis {@link
51	     * dev.thedocruby.resounding.raycast.FrustumLod#wouldDoubleCover} isolates for its own polarity
52	     * check) — zeroing the other two so off-axis ray motion can't dilute the alignment. The
53	     * position term (the offset from {@code incidentPoint} to {@code octantCenter}) is deliberately
54	     * left unrestricted. Falls back to {@code normalize(rayNorm)} when the offset is degenerate and
55	     * the restricted ray is also zero, or when the final sum is degenerate.
56	     */
57	    public static Vec3d dualDerivedNorm(
58	            @NotNull Vec3d rayNorm, @NotNull Vec3d incidentPoint, @NotNull Vec3d octantCenter, @NotNull Vec3d polNorm
59	    ) {
60	        Vec3d rn = rayNorm.normalize();
61	        Vec3d restrictedRn = restrictToDominantAxis(rn, polNorm);
62	        Vec3d offset = octantCenter.subtract(incidentPoint);
63	        if (offset.lengthSquared() < 1e-12) {
64	            return restrictedRn.lengthSquared() < 1e-12 ? rn : restrictedRn.normalize();
65	        }
66	        Vec3d offsetNorm = offset.normalize();
67	        Vec3d sum = restrictedRn.add(offsetNorm);
68	        if (sum.lengthSquared() < 1e-12) {
69	            return rn;
70	        }
71	        return sum.normalize();
72	    }
