74	    /**
75	     * Zeroes every component of {@code v} except the one on {@code axisSource}'s dominant axis
76	     * (largest absolute component; ties favor X then Y).
77	     */
78	    private static Vec3d restrictToDominantAxis(@NotNull Vec3d v, @NotNull Vec3d axisSource) {
79	        return switch (dominantAxis(axisSource)) {
80	            case 0 -> new Vec3d(v.x, 0, 0);
81	            case 1 -> new Vec3d(0, v.y, 0);
82	            default -> new Vec3d(0, 0, v.z);
83	        };
84	    }
85	
86	    /** Index (0=X, 1=Y, 2=Z) of {@code v}'s largest-magnitude component; ties favor X then Y. */
87	    private static int dominantAxis(@NotNull Vec3d v) {
88	        int axis = 0;
89	        double best = Math.abs(v.x);
90	        if (Math.abs(v.y) > best) {
91	            axis = 1;
92	            best = Math.abs(v.y);
93	        }
94	        if (Math.abs(v.z) > best) {
95	            axis = 2;
96	        }
97	        return axis;
98	    }
