102	     */
103	    public static double dualDerivedAlignment(@NotNull Vec3d rayNorm, @NotNull Vec3d incidentPoint, @NotNull Vec3d octantCenter, @NotNull Vec3d polNorm) {
104	        return polarAlignment(dualDerivedNorm(rayNorm, incidentPoint, octantCenter, polNorm), polNorm);
105	    }
