107	    /**
108	     * Orients {@code polNorm} to always face the ray it's interacting with: each axis's sign is
109	     * copied from {@code rayNorm} onto {@code polNorm}'s magnitude on that axis (same per-component
110	     * sign-copy idiom as {@link #permeationBend}), guaranteeing {@code dot(result, rayNorm) >= 0}.
111	     *
112	     * <p>{@code polar} is baked ({@code Polarization#bakeOctant}) as "points toward the
113	     * higher-impedance corner cluster" — a fixed property of the octant's own corner layout,
114	     * independent of which side of the gradient any particular ray approaches from. Feeding that
115	     * raw direction straight into {@link #grazeBend}/{@link #permeationBend} (which both assume
116	     * {@code polNorm} already faces the incoming ray) is only correct for approaches where the
117	     * baked sign happens to agree — roughly half of them; the other half see it pointing away and
118	     * get bent/permeated backwards. The result of this method (call it {@code
119	     * PolarityIncidentNormal}) is what should be passed to those two functions instead of the raw
120	     * baked direction.
121	     */
122	    public static @NotNull Vec3d polarityIncidentNormal(@NotNull Vec3d polNorm, @NotNull Vec3d rayNorm) {
123	        return new Vec3d(
124	                Math.copySign(polNorm.x, rayNorm.x),
125	                Math.copySign(polNorm.y, rayNorm.y),
126	                Math.copySign(polNorm.z, rayNorm.z)
127	        );
128	    }
