130	    /**
131	     * Blend weight {@code w = clamp(a * s, 0, 1)}. {@code w = 1} &rarr; fully committed to the
132	     * primary (high-impedance) material; {@code w = 0} &rarr; fully committed to the secondary.
133	     * Not yet implemented &mdash; always throws.
134	     */
135	    public static double polarBlendWeight(double alignment, double s) {
136	        return Math.max(0.0, Math.min(1.0, alignment * s));
137	    }
