139	    /**
140	     * Effective impedance {@code = primary.impedance * w + secondary.impedance * (1 - w)}. Not
141	     * yet implemented &mdash; always throws.
142	     */
143	    public static double blendImpedance(double primaryImpedance, double secondaryImpedance, double w) {
144	        return primaryImpedance * w + secondaryImpedance * (1 - w);
145	    }
