147	    /**
148	     * Permeation sign-copy bending (frustums-plan.md "Which vector to copy against — resolved,
149	     * replaces the earlier hard cutoff with a smooth lerp"): given the raw incident vector
150	     * {@code ray} (its magnitude is preserved verbatim, only signs may change), its normalized
151	     * direction {@code rayNorm}, and the octant's {@code polNorm}, computes
152	     * {@code dot = polNorm·rayNorm}, {@code similarity = |dot|*dot}, {@code tangent = rayNorm -
153	     * dot*polNorm}, {@code t = clamp(similarity, 0, 1)}, {@code target = lerp(tangent, polNorm,
154	     * t)}, then copies {@code target}'s per-component sign onto {@code ray}'s per-component
155	     * magnitude. {@code |result| == |ray|} always (only sign bits change). Not yet implemented
156	     * &mdash; always throws.
157	     */
158	    public static @NotNull Vec3d permeationBend(@NotNull Vec3d ray, @NotNull Vec3d rayNorm, @NotNull Vec3d polNorm) {
159	        double dot = polNorm.dotProduct(rayNorm);
160	        double similarity = Math.abs(dot) * dot;
161	        Vec3d tangent = rayNorm.subtract(polNorm.multiply(dot));
162	        double t = Math.max(0.0, Math.min(1.0, similarity));
163	        Vec3d target = tangent.multiply(1 - t).add(polNorm.multiply(t));
164	        return new Vec3d(
165	                Math.copySign(ray.x, target.x),
166	                Math.copySign(ray.y, target.y),
167	                Math.copySign(ray.z, target.z)
168	        );
169	    }
170	
171	    /**
172	     * Free graze-refraction bend toward the open half when frustum growth would double-cover past
173	     * the polarity plane. Partial flip damped by plain {@link #polarAlignment} (not dual-derived).
174	     * Magnitude of {@code ray} is preserved.
175	     */
176	    public static @NotNull Vec3d grazeBend(@NotNull Vec3d ray, @NotNull Vec3d rayNorm, @NotNull Vec3d polNorm) {
177	        double n = polNorm.dotProduct(rayNorm);
178	        if (n <= 0) {
179	            return ray; // already heading away from solid
180	        }
181	        double align = polarAlignment(rayNorm, polNorm);
182	        Vec3d tangent = rayNorm.subtract(polNorm.multiply(n));
183	        Vec3d bent = tangent.subtract(polNorm.multiply(n * (1.0 - align)));
184	        return bent.normalize().multiply(ray.length());
185	    }
