187	    /**
188	     * Contrast-magnitude threshold a face-hit's polarization contrast must clear to be "notable"
189	     * (frustums-plan.md "Notable-interaction gate decides whether"). Dynamic, tied to the beam's
190	     * remaining split budget (generic here so a later beam-tracing subagent can feed it Phase 1's
191	     * per-footprint-size-tier budget): more {@code splitsRemaining} left must lower the threshold
192	     * (splits more readily); the threshold rises as budget depletes. Not yet implemented &mdash;
193	     * always throws.
194	     */
195	    public static double notableThreshold(int splitsRemaining) {
196	        // Monotonically non-increasing in splitsRemaining (more budget -> lower/equal threshold,
197	        // splits more readily), strictly decreasing across the whole 0..4 budget range used by
198	        // Phase 1's per-size-tier split cap.
199	        return 1.0 / (1 + Math.max(0, splitsRemaining));
200	    }
201	
202	    /**
203	     * Binary decide-whether gate: is this face-hit's {@code contrastMagnitude} notable given
204	     * {@code splitsRemaining} split budget left? Not yet implemented &mdash; always throws.
205	     */
206	    public static boolean isNotableInteraction(double contrastMagnitude, int splitsRemaining) {
207	        // Exhausted split budget: commit only — never authorize another split, even at full contrast.
208	        if (splitsRemaining <= 0) {
209	            return false;
210	        }
211	        return contrastMagnitude >= notableThreshold(splitsRemaining);
212	    }
213	
214	    /**
215	     * Flat commit cutoff used once a beam's split budget is fully exhausted (frustums-plan.md:
216	     * "the beam must commit to exactly one of reflect/permeate, decided by a flat {@code w >= 0.5}
217	     * &rarr; reflect / {@code w < 0.5} &rarr; permeate cutoff on the blend weight above"). Not yet
218	     * implemented &mdash; always throws.
219	     */
220	    public static boolean commitReflect(double w) {
221	        return w >= 0.5;
222	    }
