287	            rstep = geometry.reflectStep();
288	            shapeEntryStep = geometry.entryStep();
289	            pdistance = geometry.permeationDistance();
290	            pposition = geometry.transmitPosition();
291	            rdistance = geometry.reflectDistance();
292	            rposition = geometry.reflectPosition();
