471	                    this.lastFreeRefraction = true;
472	                    if (polar != null && polar.lengthSquared() > 1e-12) {
473	                        Vec3d rayNorm = vector.normalize();
474	                        Vec3d incidentNormal = Physics.polarityIncidentNormal(polar.normalize(), rayNorm);
475	                        vector = Physics.grazeBend(vector, rayNorm, incidentNormal);
