533	                ? vector
534	                : Physics.pseudoReflect(vector, transmitPlane, transmission / 5);
535	        Vec3d reflectStart = gridAlignedReflect ? rposition : nudgeReflectOrigin(rposition, reflectedDir, rdistance);
