538	            reflectStart = FrustumLod.edgeWalk(
539	                    reflectStart, cellBase, cellSize, reflectPlane, vector, 0.85, forwardInteraction);
540	            rdistance = reflectStart.subtract(position).length();
541	        }
542	        // } */
543	        // apply movement
544	        reflect(reflectivity * power, reflectStart, reflectedDir, rdistance);
545	        transmit(transmission * power, pposition, transmitted, pdistance);
