559	    /** Combined result of {@link #surveyForward}: the four-map interaction classification. */
560	    private record ForwardSurvey(FrustumLod.Interaction interaction) {}
561	
562	    /**
563	     * Surveys N/E/D at the same LOD as {@code cellOrigin} for the four-map interaction
564	     * (host→neighbor interaction permeate, {@link FrustumLod#blocksPermeation}; missing neighbors
565	     * count as open). Returns {@code null} when the DDA projection says this exit is a single-axis
566	     * (non-NED) step.
567	     */
568	    private @Nullable ForwardSurvey surveyForward(
569	            BlockPos cellOrigin,
570	            Vec3d cellBase,
571	            int cellSize,
572	            Vec3d hitPos,
573	            Vec3i face,
574	            Vec3d rayDir,
575	            double hostImpedance
576	    ) {
577	        FrustumLod.ForwardMap map = FrustumLod.forwardMap(cellBase, cellSize, hitPos, rayDir, face);
578	        if (map == null) {
579	            return null;
580	        }
581	
582	        Branch nBranch = lodAt(cellOrigin.add(map.nOffset().getX(), map.nOffset().getY(), map.nOffset().getZ()), cellSize);
583	        NeighborSample n = sampleNeighbor(nBranch);
584	        boolean nBlocks = FrustumLod.blocksPermeation(hostImpedance, n.impedance(), n.permeation());
585	
586	        boolean eBlocks = false;
587	        boolean dBlocks = nBlocks;
588	        if (map.hasTangent()) {
589	            Branch eBranch = lodAt(cellOrigin.add(map.eOffset().getX(), map.eOffset().getY(), map.eOffset().getZ()), cellSize);
590	            NeighborSample e = sampleNeighbor(eBranch);
591	            eBlocks = FrustumLod.blocksPermeation(hostImpedance, e.impedance(), e.permeation());
592	
593	            Branch dBranch = lodAt(cellOrigin.add(map.dOffset().getX(), map.dOffset().getY(), map.dOffset().getZ()), cellSize);
594	            NeighborSample d = sampleNeighbor(dBranch);
595	            dBlocks = FrustumLod.blocksPermeation(hostImpedance, d.impedance(), d.permeation());
596	        }
597	
598	        return new ForwardSurvey(FrustumLod.classify(nBlocks, eBlocks, dBlocks));
599	    }
