601	    /** One neighbor's impedance + permeation, sampled from a single {@code descriptor}/{@code
602	     *  material} read each so both values come from the same baked generation — reading them via
603	     *  two separate accessor calls let a concurrent rebake land in between, mixing an old
604	     *  impedance with a new permeation (or vice versa) for the same neighbor. */
605	    private record NeighborSample(double impedance, double permeation) {
606	        static final NeighborSample MISSING = new NeighborSample(Double.NaN, Double.NaN);
607	    }
608	
609	    private static NeighborSample sampleNeighbor(@Nullable Branch b) {
610	        if (b == null) {
611	            return NeighborSample.MISSING;
612	        }
613	        // One descriptor read + one material read, reused for both impedance and permeation —
614	        // two independent Branch.effectiveImpedance()/effectivePermeation() calls would each read
615	        // `material` on their own and could straddle a concurrent rebake.
616	        Branch.NodeDescriptor d = b.descriptor;
617	        Material material = b.material;
618	        double impedance = !Double.isNaN(d.avgImpedance()) ? d.avgImpedance()
619	                : !Double.isNaN(d.mostCommonImpedance()) ? d.mostCommonImpedance()
620	                : material != null ? material.impedance() : Double.NaN;
621	        double permeation = material != null ? material.permeation() : 1.0;
622	        return new NeighborSample(impedance, permeation);
623	    }
624	
625	    private @Nullable Branch lodAt(BlockPos pos, int lod) {
626	        if (chunk != null) {
627	            ChunkChain c = chunk.access(pos.getX() >> 4, pos.getZ() >> 4);
628	            if (c != null) {
629	                Branch root = c.getBranch(pos.getY() >> 4);
630	                if (root != null) {
631	                    return root.getAtLod(pos, lod);
632	                }
633	            }
634	        }
635	        return tree == null ? null : tree.getAtLod(pos, lod);
636	    }
