638	    private static double polarizedImpedance(Branch.NodeDescriptor descriptor, Vec3d vector, Vec3d incidentPoint, Vec3d octantCenter) {
639	        double w = polarBlendWeight(descriptor, vector, incidentPoint, octantCenter);
640	        return Physics.blendImpedance(descriptor.mostCommonImpedance(), descriptor.leastCommonImpedance(), w);
641	    }
642	
643	    private static double polarBlendWeight(Branch.NodeDescriptor descriptor, Vec3d vector, Vec3d incidentPoint, Vec3d octantCenter) {
644	        Vec3d pol = descriptor.polar();
645	        if (pol == null || pol.lengthSquared() < 1e-12) {
646	            return 0.5;
647	        }
648	        double blend = descriptor.blendCoefficient();
649	        double s = !Double.isNaN(blend) && blend >= 0.75 ? 2.0 : 1.0;
650	        return Physics.polarBlendWeight(
651	                Physics.dualDerivedAlignment(vector.normalize(), incidentPoint, octantCenter, pol.normalize()), s);
652	    }
653	
654	    private static double polarContrast(Branch.NodeDescriptor descriptor) {
655	        double most = descriptor.mostCommonImpedance();
656	        double least = descriptor.leastCommonImpedance();
657	        double denom = Math.max(Math.abs(most), Math.abs(least));
658	        if (denom < 1e-9 || Double.isNaN(denom)) {
659	            return 0.0;
660	        }
661	        return Math.abs(most - least) / denom;
662	    }
