664	    /**
665	     * Prior medium for boundary physics. An unset {@code impeded} means the ray is being born in
666	     * {@code mediumImpedance}, so {@code unset:air} and {@code unset:stone} behave like matched pairs.
667	     * Entering vacuum ({@code stone:null}) is handled separately and must not use this shortcut.
668	     */
669	    static double priorImpedanceForCast(boolean impededSet, double impeded, double mediumImpedance) {
670	        return impededSet ? impeded : mediumImpedance;
671	    }
