673	    /**
674	     * Samples the six face neighbors of {@link #originBlock} and the born-in medium impedance
675	     * before any rays launch, so the first emission exit can reflect into stiffer neighbors
676	     * instead of permeating freely.
677	     */
678	    public void prepareEmissionContext(Vec3d soundPos) {
679	        emissionNeighborImpedances = new double[FACE_OFFSETS.length];
680	        emissionNeighborAverageImpedance = Double.NaN;
681	        emissionSourceImpedance = Double.NaN;
682	        if (originBlock == null || world == null || chunk == null) {
683	            return;
684	        }
685	
686	        chunk = chunk.access(originBlock.getX() >> 4, originBlock.getZ() >> 4);
687	        if (chunk == null) {
688	            return;
689	        }
690	
691	        BlockState originState = ((WorldChunk) chunk).getBlockState(originBlock);
692	        VoxelShape originShape = originState.getCollisionShape(world, originBlock);
693	        Material originMaterial = material(originState);
694	        emissionSourceImpedance = interactionMaterial(
695	                originMaterial, originShape, originBlock, soundPos, ShapeTraversal.Mode.VOXEL
696	        ).impedance();
697	
698	        double sum = 0.0;
699	        for (int i = 0; i < FACE_OFFSETS.length; i++) {
700	            double neighborImpedance = impedanceAtBlock(originBlock.add(FACE_OFFSETS[i]));
701	            emissionNeighborImpedances[i] = neighborImpedance;
702	            sum += neighborImpedance;
703	        }
704	        emissionNeighborAverageImpedance = sum / FACE_OFFSETS.length;
705	    }
706	
707	    static BlockPos neighborOffsetForExitPlane(Vec3i plane) {
708	        return new BlockPos(-plane.getX(), -plane.getY(), -plane.getZ());
709	    }
710	
711	    static boolean shouldReflectAtEmissionExit(double targetImpedance, double neighborAverage, double sourceImpedance) {
712	        return Double.isFinite(targetImpedance)
713	                && Double.isFinite(neighborAverage)
714	                && Double.isFinite(sourceImpedance)
715	                && targetImpedance > neighborAverage
716	                && targetImpedance > sourceImpedance;
717	    }
718	
719	    boolean shouldReflectAtEmissionExit(Vec3i exitPlane) {
720	        return shouldReflectAtEmissionExit(
721	                neighborImpedanceForExitPlane(exitPlane),
722	                emissionNeighborAverageImpedance,
723	                emissionSourceImpedance
724	        );
725	    }
726	
727	    double neighborImpedanceForExitPlane(Vec3i plane) {
728	        if (emissionNeighborImpedances == null) {
729	            return Double.NaN;
730	        }
731	        BlockPos offset = neighborOffsetForExitPlane(plane);
732	        for (int i = 0; i < FACE_OFFSETS.length; i++) {
733	            if (FACE_OFFSETS[i].equals(offset)) {
734	                return emissionNeighborImpedances[i];
735	            }
736	        }
737	        return Double.NaN;
738	    }
