740	    private double impedanceAtBlock(BlockPos pos) {
741	        if (chunk == null || world == null) {
742	            return MaterialRegistry.DEFAULT.impedance();
743	        }
744	        chunk = chunk.access(pos.getX() >> 4, pos.getZ() >> 4);
745	        if (chunk == null) {
746	            return MaterialRegistry.DEFAULT.impedance();
747	        }
