52	     * share one impedance); a real {@code (0,0,0)} polar means a heterogeneous octant whose
53	     * corner-sign-sum genuinely cancels — the two are deliberately distinguishable.
54	     *
55	     * <p>{@code mostCommonImpedance}/{@code leastCommonImpedance} store {@code g_most}/{@code
56	     * g_least} — presence-split endpoints (not raw max/min impedance). Alignment lerps from
57	     * most-common (primary, {@code w=1}) toward least-common (secondary, {@code w=0}).
58	     */
59	    public record Descriptor(
60	            double mostCommonImpedance,
61	            double leastCommonImpedance,
62	            double avgImpedance,
63	            @Nullable Vec3d polar,
64	            @Nullable Material primary,
65	            @Nullable Material secondary,
66	            double blendCoefficient,
67	            double s
68	    ) {}
