70	    /**
71	     * Presence-split impedance adjuster:
72	     * {@code f(mostly_mean, other_mean, overall_ratio) = other_mean * (1 - overall_ratio²)
73	     * + mostly_mean * √overall_ratio} for {@code overall_ratio ∈ (0,1)}.
74	     *
75	     * <p>{@code overall_ratio} is a presence fraction. Callers that pass a count ratio
76	     * ({@code mostCount/leastCount}) may exceed 1 — that is treated as fully committed to the
77	     * mostly-group ({@code → mostlyMean}). Without that clamp, {@code 1 - ratio²} goes negative and
78	     * soft-majority octants (air+wool, etc.) bake huge negative endpoints that Cast treats as vacuum.
79	     */
80	    public static double groupAdjust(double mostlyMean, double otherMean, double overallRatio) {
81	        if (!Double.isFinite(mostlyMean) || !Double.isFinite(otherMean)) {
82	            return Double.NaN;
83	        }
84	        if (!Double.isFinite(overallRatio) || !(overallRatio > 0.0)) {
85	            return otherMean;
86	        }
87	        if (overallRatio >= 1.0) {
88	            return mostlyMean;
89	        }
90	        return otherMean * (1.0 - overallRatio * overallRatio)
91	                + mostlyMean * Math.sqrt(overallRatio);
92	    }
93	
94	    /**
95	     * Bakes the size-2 (8-child) octant descriptor from 8 corner materials in {@code blockSequence}
96	     * order.
97	     * <ul>
98	     *   <li>Polar: every corner joins the top or bottom impedance half (middle tier included).</li>
99	     *   <li>Primary/secondary: most-common / least-common materials (presence ties → stiffer
100	     *       primary, softer secondary).</li>
101	     *   <li>{@code g_most}/{@code g_least}: {@link #groupAdjust} over those material groups'
102	     *       means and count ratio — presence endpoints, not impedance extremes.</li>
103	     * </ul>
104	     */
105	    public static @NotNull Descriptor bakeOctant(@NotNull Material[] corners) {
106	        if (corners.length != 8) {
107	            throw new IllegalArgumentException("bakeOctant requires exactly 8 corners in blockSequence order");
108	        }
109	
110	        double[] impedances = new double[8];
111	        double sum = 0.0;
112	        double max = Double.NEGATIVE_INFINITY;
113	        double min = Double.POSITIVE_INFINITY;
114	        for (int i = 0; i < 8; i++) {
115	            double v = corners[i].impedance();
116	            impedances[i] = v;
117	            sum += v;
118	            if (v > max) max = v;
119	            if (v < min) min = v;
120	        }
121	        double avg = sum / 8.0;
122	
123	        if (max == min) {
124	            return new Descriptor(max, min, avg, null, null, null, Double.NaN, Double.NaN);
125	        }
126	
127	        // Polar membership: impedance-ranked top/bottom halves (all 8 corners, no middle drop).
128	        Integer[] order = {0, 1, 2, 3, 4, 5, 6, 7};
129	        Arrays.sort(order, Comparator
130	                .comparingDouble((Integer i) -> impedances[i])
131	                .thenComparingInt(i -> i));
132	        boolean[] inHigh = new boolean[8];
133	        for (int r = 4; r < 8; r++) {
134	            inHigh[order[r]] = true;
135	        }
136	
137	        Vec3d highDir = Vec3d.ZERO;
138	        Vec3d lowDir = Vec3d.ZERO;
139	        for (int i = 0; i < 8; i++) {
140	            Vec3d sign = cornerSign(CORNER_OFFSETS[i]);
141	            if (inHigh[i]) {
142	                highDir = highDir.add(sign);
143	            } else {
144	                lowDir = lowDir.add(sign);
145	            }
146	        }
147	        Vec3d polar = highDir.subtract(lowDir);
148	
149	        Material primary = selectMostCommon(corners);
150	        Material secondary = selectLeastCommon(corners, primary);
151	
152	        double mostSum = 0.0;
153	        double leastSum = 0.0;
154	        int mostCount = 0;
155	        int leastCount = 0;
156	        for (int i = 0; i < 8; i++) {
157	            if (corners[i].equals(primary)) {
158	                mostSum += impedances[i];
159	                mostCount++;
160	            } else if (corners[i].equals(secondary)) {
161	                leastSum += impedances[i];
162	                leastCount++;
163	            }
164	        }
165	        if (mostCount == 0 || leastCount == 0) {
166	            throw new IllegalStateException("heterogeneous octant must have both most- and least-common corners");
167	        }
168	
169	        double meanMost = mostSum / mostCount;
170	        double meanLeast = leastSum / leastCount;
171	        double gMost = groupAdjust(meanMost, meanLeast, (double) mostCount / leastCount);
172	        double gLeast = groupAdjust(meanLeast, meanMost, (double) leastCount / mostCount);
173	
174	        double blendCoefficient = mostCount / 8.0;
175	        double s = magnitudeTerm(mostCount);
176	
177	        return new Descriptor(gMost, gLeast, avg, polar, primary, secondary, blendCoefficient, s);
178	    }
179	
180	    /** Most-common material; presence ties broken toward the stiffer (higher-impedance) material. */
181	    private static @NotNull Material selectMostCommon(@NotNull Material[] corners) {
182	        Map<Material, Integer> counts = countMaterials(corners);
183	        Material best = corners[0];
184	        int bestCount = -1;
185	        for (Map.Entry<Material, Integer> e : counts.entrySet()) {
186	            Material m = e.getKey();
187	            int c = e.getValue();
188	            if (c > bestCount
189	                    || (c == bestCount && m.impedance() > best.impedance())) {
190	                best = m;
191	                bestCount = c;
192	            }
193	        }
194	        return best;
195	    }
196	
197	    /**
198	     * Least-common material among those that are not primary; presence ties broken toward the
199	     * softer (lower-impedance) material.
200	     */
201	    private static @NotNull Material selectLeastCommon(@NotNull Material[] corners, @NotNull Material primary) {
202	        Map<Material, Integer> counts = countMaterials(corners);
203	        Material best = null;
204	        int bestCount = Integer.MAX_VALUE;
205	        for (Map.Entry<Material, Integer> e : counts.entrySet()) {
206	            Material m = e.getKey();
207	            if (m.equals(primary)) {
208	                continue;
209	            }
210	            int c = e.getValue();
211	            if (best == null
212	                    || c < bestCount
213	                    || (c == bestCount && m.impedance() < best.impedance())) {
214	                best = m;
215	                bestCount = c;
216	            }
217	        }
218	        if (best == null) {
219	            throw new IllegalStateException("heterogeneous octant must have a least-common material");
220	        }
221	        return best;
222	    }
223	
224	    private static @NotNull Map<Material, Integer> countMaterials(@NotNull Material[] corners) {
225	        Map<Material, Integer> counts = new HashMap<>();
226	        for (Material m : corners) {
227	            counts.merge(m, 1, Integer::sum);
228	        }
229	        return counts;
230	    }
