232	    /**
233	     * Magnitude/gain term {@code s}: {@code 1} by default, {@code 2} when the primary (most-common)
234	     * material's count is &ge;6 of the octant's 8 children.
235	     */
236	    public static double magnitudeTerm(int primaryCount) {
237	        return primaryCount >= 6 ? 2.0 : 1.0;
238	    }
239	
240	    /**
241	     * {@code stiff_weight(child) ∈ [0,1]} (frustums-plan.md size&gt;2 combination rule): how
242	     * presence-dominant a child octant is, quantized to quarters (25%/50%/75%/100%).
243	     */
244	    public static double stiffWeight(double blendCoefficient) {
245	        return Math.round(blendCoefficient * 4.0) / 4.0;
246	    }
247	
248	    /**
249	     * {@code combined = Σ(child.polar × stiff_weight(child)) / Σ(stiff_weight(child))},
250	     * component-wise, <b>not</b> renormalized to unit length afterward (frustums-plan.md size&gt;2
251	     * combination rule).
252	     */
253	    public static @NotNull Vec3d combinePolar(@NotNull Vec3d[] childPolar, double[] childStiffWeight) {
254	        double sumWeight = 0.0;
255	        double x = 0.0, y = 0.0, z = 0.0;
256	        for (int i = 0; i < childPolar.length; i++) {
257	            double w = childStiffWeight[i];
258	            Vec3d p = childPolar[i];
259	            x += p.x * w;
260	            y += p.y * w;
261	            z += p.z * w;
262	            sumWeight += w;
263	        }
264	        if (sumWeight == 0.0) {
265	            return Vec3d.ZERO;
266	        }
267	        return new Vec3d(x / sumWeight, y / sumWeight, z / sumWeight);
268	    }
